// Documented Claude Code environment variables a person might set in settings.json -> env (from env-vars.md), grouped,
// with an English and a Persian description. Variables that hold a secret are flagged so the UI masks their values.
// Left out on purpose: variables Claude Code sets itself (CLAUDECODE, CLAUDE_PID, CLAUDE_CODE_SESSION_ID, ...),
// variables the docs list as removed or without effect, and ones only meant for Agent SDK hosts.
//
// This file registers nothing; settings-env.js imports it. It does not touch the DOM (so it also loads in Node).

// v(name, English, Persian, secret?)
const v = (name, en, fa, secret = false) => ({ name, en, fa, secret });

const VERTEX_MODELS = [
  ["3_5_HAIKU", "Claude 3.5 Haiku"], ["3_5_SONNET", "Claude 3.5 Sonnet"], ["3_7_SONNET", "Claude 3.7 Sonnet"],
  ["4_0_OPUS", "Claude Opus 4"], ["4_0_SONNET", "Claude Sonnet 4"], ["4_1_OPUS", "Claude Opus 4.1"],
  ["4_5_OPUS", "Claude Opus 4.5"], ["4_5_SONNET", "Claude Sonnet 4.5"], ["4_6_OPUS", "Claude Opus 4.6"], ["4_6_SONNET", "Claude Sonnet 4.6"],
  ["4_7_OPUS", "Claude Opus 4.7"], ["4_8_OPUS", "Claude Opus 4.8"], ["5_OPUS", "Claude Opus 5"], ["5_SONNET", "Claude Sonnet 5"],
  ["5_5_OPUS", "Claude Opus 5.5"], ["5_5_SONNET", "Claude Sonnet 5.5"], ["FABLE_5", "Claude Fable 5"], ["FABLE_5_1", "Claude Fable 5.1"],
  ["FABLE_5_2", "Claude Fable 5.2"], ["HAIKU_4_5", "Claude Haiku 4.5"], ["HAIKU_5_5", "Claude Haiku 5.5"],
].map(([suffix, model]) =>
  v(`VERTEX_REGION_CLAUDE_${suffix}`, `Override the region for ${model} on Google Cloud's Agent Platform.`, `منطقهٔ ${model} را در Google Cloud's Agent Platform بازنویسی می‌کند.`),
);

const PINNED_MODELS = [
  ["OPUS", "Opus", "opus", "The model ID the opus alias resolves to; opusplan uses it while Plan Mode is active.", "شناسهٔ مدلی که نام مستعار opus به آن اشاره می‌کند؛ opusplan در حالت Plan از آن استفاده می‌کند."],
  ["SONNET", "Sonnet", "sonnet", "The model ID the sonnet alias resolves to; opusplan uses it when Plan Mode is not active.", "شناسهٔ مدلی که نام مستعار sonnet به آن اشاره می‌کند؛ opusplan بیرون از حالت Plan از آن استفاده می‌کند."],
  ["HAIKU", "Haiku", "haiku", "The model ID the haiku alias resolves to; also used for background functionality.", "شناسهٔ مدلی که نام مستعار haiku به آن اشاره می‌کند؛ برای کارهای پس‌زمینه هم استفاده می‌شود."],
  ["FABLE", "Fable", "fable", "The model ID the fable alias resolves to, also recognized as a Fable model for automatic fallback on third-party providers.", "شناسهٔ مدلی که نام مستعار fable به آن اشاره می‌کند؛ برای جایگزینی خودکار روی ارائه‌دهندگان دیگر هم به‌عنوان مدل Fable شناخته می‌شود."],
].flatMap(([key, label, , idEn, idFa]) => [
  v(`ANTHROPIC_DEFAULT_${key}_MODEL`, idEn, idFa),
  v(`ANTHROPIC_DEFAULT_${key}_MODEL_NAME`, `Display name of the pinned ${label} model in the /model picker.`, `نام نمایشی مدل ${label} سنجاق‌شده در انتخابگر /model.`),
  v(`ANTHROPIC_DEFAULT_${key}_MODEL_DESCRIPTION`, `Display description of the pinned ${label} model in the /model picker.`, `توضیح نمایشی مدل ${label} سنجاق‌شده در انتخابگر /model.`),
  v(`ANTHROPIC_DEFAULT_${key}_MODEL_SUPPORTED_CAPABILITIES`, `Comma-separated capabilities the pinned ${label} model supports, for example effort,thinking.`, `قابلیت‌هایی (جداشده با ویرگول) که مدل ${label} سنجاق‌شده پشتیبانی می‌کند، مثل effort,thinking.`),
]);

