export const ENV_VARS = ENV_GROUPS.flatMap((group) => group.vars.map((entry) => ({ ...entry, group: group.id })));
export const ENV_BY_NAME = new Map(ENV_VARS.map((entry) => [entry.name, entry]));

// Names that carry a secret even when the docs do not list them (matches the masking that existed before).
// Token budgets such as MAX_THINKING_TOKENS are numbers, not secrets.
const SECRET_NAME = /(KEY|TOKEN|SECRET|PASSWORD|PASSWD|PASSPHRASE|CREDENTIAL|AUTH|HEADERS|BEARER)/i;

/** True when the value of this variable should be masked in the UI. */
export function isSecretName(name) {
  const known = ENV_BY_NAME.get(name);
  if (known) return known.secret;
  if (/TOKENS$/i.test(name) || /(?:^|_)(?:MODEL|TIMEOUT|TTL)/i.test(name)) return false;
  return SECRET_NAME.test(name);
}
